import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

const TWO_PI = Math.PI * 2;

const TOWER_HEIGHT = 40;
const TOWER_RADIUS_TOP = 0.8;
const TOWER_RADIUS_BOTTOM = 1.6;
const NACELLE_LENGTH = 6;
const NACELLE_SIZE = 2;
// Hub sits at the front face of the nacelle, which caps the tower.
export const HUB_OFFSET = new THREE.Vector3(
  NACELLE_LENGTH / 2,
  TOWER_HEIGHT + NACELLE_SIZE / 2,
  0
);

const BLADE_LENGTH = 18;
const HUB_RADIUS = 1.4;
const BLADE_COUNT = 3;

/**
 * Deterministic PRNG (mulberry32). Same seed -> same stream.
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * One merged geometry for the static part of a turbine:
 * tapered tower cylinder + nacelle box on top.
 */
function buildTowerNacelleGeometry() {
  const tower = new THREE.CylinderGeometry(
    TOWER_RADIUS_TOP,
    TOWER_RADIUS_BOTTOM,
    TOWER_HEIGHT,
    10
  );
  tower.translate(0, TOWER_HEIGHT / 2, 0);

  const nacelle = new THREE.BoxGeometry(NACELLE_LENGTH, NACELLE_SIZE, NACELLE_SIZE);
  nacelle.translate(0, TOWER_HEIGHT + NACELLE_SIZE / 2, 0);

  return mergeGeometries([tower, nacelle]);
}

/**
 * Rotor geometry: hub sphere + BLADE_COUNT blades merged into one geometry,
 * so a whole rotor can be spun with a single instance matrix.
 */
function buildRotorGeometry() {
  const parts = [new THREE.SphereGeometry(HUB_RADIUS, 12, 8)];
  for (let b = 0; b < BLADE_COUNT; b++) {
    const blade = new THREE.BoxGeometry(1.4, BLADE_LENGTH, 0.35);
    // Pivot the blade at its inner end, offset by the hub radius.
    blade.translate(0, HUB_RADIUS + BLADE_LENGTH / 2, 0);
    blade.rotateZ((b * TWO_PI) / BLADE_COUNT);
    parts.push(blade);
  }
  return mergeGeometries(parts);
}

/**
 * Recompose one rotor's instance matrix: rotation about Z by `phase`,
 * translated to the rotor origin (tower position + hub offset).
 */
function composeRotorMatrix(matrix, x, y, z, phase) {
  matrix.makeRotationZ(phase);
  matrix.setPosition(x, y, z);
  return matrix;
}

/**
 * Build an instanced wind farm.
 *
 * @returns {{
 *   rows: number, cols: number, count: number, spacing: number, seed: number,
 *   towers: THREE.InstancedMesh,
 *   rotors: THREE.InstancedMesh,
 *   positions: THREE.Vector3[],
 *   phases: Float32Array,
 *   speeds: Float32Array,
 *   hubOffset: THREE.Vector3
 * }}
 */
export function buildFarm({ rows, cols, spacing = 80, seed = 1 }) {
  const count = rows * cols;

  const rng = mulberry32(seed);
  const phases = new Float32Array(count);
  const speeds = new Float32Array(count);
  const positions = [];
  for (let i = 0; i < count; i++) {
    phases[i] = rng() * TWO_PI;
    speeds[i] = 0.8 + rng() * 0.8; // rad/s in [0.8, 1.6]
  }

  const material = new THREE.MeshStandardMaterial();

  // Static structure: one merged tower+nacelle geometry, one instance per turbine.
  const towers = new THREE.InstancedMesh(buildTowerNacelleGeometry(), material, count);

  // Rotors: separate InstancedMesh so each can spin independently via its matrix.
  const rotors = new THREE.InstancedMesh(buildRotorGeometry(), material, count);

  const matrix = new THREE.Matrix4();
  let index = 0;
  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++, index++) {
      const x = (col - (cols - 1) / 2) * spacing;
      const z = (row - (rows - 1) / 2) * spacing;
      const y = 0;
      positions.push(new THREE.Vector3(x, y, z));

      towers.setMatrixAt(index, matrix.makeTranslation(x, y, z));

      composeRotorMatrix(
        matrix,
        x + HUB_OFFSET.x,
        y + HUB_OFFSET.y,
        z + HUB_OFFSET.z,
        phases[index]
      );
      rotors.setMatrixAt(index, matrix);
    }
  }
  towers.instanceMatrix.needsUpdate = true;
  rotors.instanceMatrix.needsUpdate = true;

  return { rows, cols, count, spacing, seed, towers, rotors, positions, phases, speeds, hubOffset: HUB_OFFSET.clone() };
}

/**
 * Advance every rotor by its own seeded speed and recompose its matrix.
 */
export function spinRotors(farm, dt) {
  const { rotors, positions, phases, speeds, hubOffset, count } = farm;
  const matrix = new THREE.Matrix4();
  for (let i = 0; i < count; i++) {
    let phase = phases[i] + speeds[i] * dt;
    phase %= TWO_PI;
    if (phase < 0) phase += TWO_PI;
    phases[i] = phase;

    const p = positions[i];
    composeRotorMatrix(
      matrix,
      p.x + hubOffset.x,
      p.y + hubOffset.y,
      p.z + hubOffset.z,
      phase
    );
    rotors.setMatrixAt(i, matrix);
  }
  rotors.instanceMatrix.needsUpdate = true;
}

